//! Tauri host process for the Screentime UI.
//!
//! Every command exposed here is a thin adapter over an IPC call to the
//! `screentime-agent`. Do not put business logic in this crate: the agent is
//! the source of truth, and duplicating rules in the UI process is how they
//! stop agreeing.
//!
//! Payload policy: `st-ipc` DTOs are serialized *verbatim* — no host-side
//! re-mapping into different field names. That keeps the TypeScript bindings
//! generated by ts-rs (ui/src/types/generated/) byte-compatible with what the
//! commands actually return; any drift between the two would be caught by the
//! compiler instead of at runtime.
//!
//! Error policy: failures cross the boundary as a structured
//! `{ code, message }` object rather than a formatted string, so the UI can
//! map machine codes (bad_pin, cooldown_active, …) to friendly copy without
//! parsing English.

mod ipc_client;
mod tray;

#[cfg(windows)]
mod corners {
    use std::mem::size_of;
    use windows::Win32::Foundation::HWND;
    use windows::Win32::Graphics::Dwm::{
        DwmSetWindowAttribute, DWMWA_WINDOW_CORNER_PREFERENCE, DWMWCP_DONOTROUND,
    };

    pub(crate) const SQUARE: i32 = DWMWCP_DONOTROUND.0;

    pub(crate) fn set_square_corners(hwnd: HWND) {
        let result = unsafe {
            DwmSetWindowAttribute(
                hwnd,
                DWMWA_WINDOW_CORNER_PREFERENCE,
                &SQUARE as *const i32 as *const _,
                size_of::<i32>() as u32,
            )
        };
        if let Err(e) = result {
            tracing::debug!("DwmSetWindowAttribute(SQUARE) failed: {e}");
        }
    }
}

use serde::Serialize;
use st_ipc::{ErrorCode, Response};

/// Everything the header needs, plus one host-owned fact: whether the IPC
/// round trip succeeded at all. `StatusDto` describes the agent's own state;
/// `agent_connected` describes the *link*, which only this process knows.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "snake_case")]
pub struct AgentStatus {
    pub version: String,
    pub agent_connected: bool,
    pub tracker_backend: String,
    pub filter_backend: String,
    pub tracking_available: bool,
    pub pin_configured: bool,
    pub strict_mode: bool,
}

/// Structured failure for every fallible command.
///
/// `code` mirrors [`st_ipc::ErrorCode`]'s snake_case wire tokens where the
/// agent refused, and extends the vocabulary with transport-level codes the
/// host owns: `unreachable` (pipe connect/send/read failed) and
/// `unexpected_response` (protocol mismatch — should be impossible).
#[derive(Debug, Clone, Serialize)]
pub struct CommandError {
    pub code: String,
    pub message: String,
}

impl CommandError {
    fn unreachable(e: st_ipc::transport::TransportError) -> Self {
        Self {
            code: "unreachable".into(),
            message: format!("agent unreachable: {e}"),
        }
    }

    fn unexpected() -> Self {
        Self {
            code: "unexpected_response".into(),
            message: "unexpected agent response".into(),
        }
    }
}

fn error_from(code: ErrorCode, message: String) -> CommandError {
    CommandError {
        code: serde_plain_string(code),
        message,
    }
}

/// Render an [`ErrorCode`] as its snake_case wire token. Kept in step with the
/// enum's `rename_all`; the serialization-stability test in st-ipc pins the
/// exact tokens.
fn serde_plain_string(code: ErrorCode) -> String {
    let json = serde_json::to_value(code).expect("unit enum variant always serializes");
    json.as_str()
        .expect("unit variant serializes as string")
        .into()
}

type CmdResult<T> = Result<T, CommandError>;

/// Snapshot of what the UI should show in its header.
///
/// This is intentionally a *description* of the current situation rather than a
/// list of individually queryable fields: the header must render a coherent
/// state (either "connected, tracking" *or* "disconnected") and splitting it
/// across several commands invites the two halves to disagree.
///
/// When the agent is not running, the command still succeeds but reports
/// `agent_connected: false` so the frontend renders a graceful banner instead
/// of an error state.
#[tauri::command]
fn get_status() -> AgentStatus {
    match ipc_client::request(st_ipc::Request::Status) {
        Ok(Response::Status(dto)) => AgentStatus {
            version: dto.agent_version,
            agent_connected: true,
            tracker_backend: dto.tracker_backend,
            filter_backend: dto.filter_backend,
            tracking_available: dto.tracking_available,
            pin_configured: dto.pin_configured,
            strict_mode: dto.strict_mode,
        },
        Ok(_) | Err(_) => AgentStatus {
            version: env!("CARGO_PKG_VERSION").to_string(),
            agent_connected: false,
            tracker_backend: if cfg!(windows) { "win32" } else { "x11-stub" }.into(),
            filter_backend: if cfg!(windows) {
                "windows-hosts"
            } else {
                "linux-stub"
            }
            .into(),
            tracking_available: false,
            pin_configured: false,
            strict_mode: false,
        },
    }
}

/// Dashboard payload for one local day, fetched from the agent.
#[tauri::command]
fn get_day_summary(day: i32) -> CmdResult<st_ipc::DaySummaryDto> {
    match ipc_client::request(st_ipc::Request::DaySummary {
        day: st_core::daykey::DayKey(day),
    }) {
        Ok(Response::DaySummary(dto)) => Ok(dto),
        Ok(Response::Error { code, message }) => Err(error_from(code, message)),
        Ok(_) => Err(CommandError::unexpected()),
        Err(e) => Err(CommandError::unreachable(e)),
    }
}

/// Weekly dashboard payload: the 7 local days ending at `endDay` (inclusive)
/// plus the previous week's total, fetched from the agent.
#[tauri::command]
fn get_weekly_summary(end_day: i32) -> CmdResult<st_ipc::WeeklySummaryDto> {
    match ipc_client::request(st_ipc::Request::WeeklySummary {
        end_day: st_core::daykey::DayKey(end_day),
    }) {
        Ok(Response::WeeklySummary(dto)) => Ok(dto),
        Ok(Response::Error { code, message }) => Err(error_from(code, message)),
        Ok(_) => Err(CommandError::unexpected()),
        Err(e) => Err(CommandError::unreachable(e)),
    }
}

