fn stop_all_services(app: tauri::AppHandle) -> CmdResult<()> {
    tray::stop_all_services(&app);
    Ok(())
}

pub fn run() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    tauri::Builder::default()
        .plugin(tauri_plugin_shell::init())
        .invoke_handler(tauri::generate_handler![
            get_status,
            get_day_summary,
            get_weekly_summary,
            get_catalog,
            set_pin,
            recover_pin,
            remove_pin,
            set_limit,
            delete_limit,
            grant_override,
            categorize,
            list_manual_blocks,
            add_manual_block,
            remove_manual_block,
            list_schedules,
            create_schedule,
            update_schedule,
            set_schedule_enabled,
            delete_schedule,
            list_allowlist,
            set_allowlist,
            get_focus_session,
            start_focus_session,
            end_focus_session,
            emergency_reset_network,
            stop_all_services
        ])
        .setup(|app| {
            #[cfg(windows)]
            {
                use tauri::Manager;
                if let Some(window) = app.get_webview_window("main") {
                    let hwnd = window.hwnd().expect("main window HWND");
                    corners::set_square_corners(hwnd);
                }
            }

            // Initialize system tray icon with menu and emergency actions
            if let Err(e) = tray::setup_tray(app) {
                tracing::warn!("Failed to initialize system tray icon: {e}");
            }

            Ok(())
        })
        .on_window_event(|window, event| {
            // Minimize to tray on close button so app continues monitoring in background
            if let tauri::WindowEvent::CloseRequested { api, .. } = event {
                let _ = window.hide();
                api.prevent_close();
            }
        })
        .run(tauri::generate_context!())
        .expect("failed to launch Tauri application");
}
